def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opponents += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0

    if not alive_opponents:
        return min(budget, 20)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    scarcity = len(alive_opponents) + 1
    likely_units = supply / float(WATER_REQ)

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if likely_units < 1.2:
        danger += 2
    elif likely_units < 1.6:
        danger += 1

    if urgent_opponents >= 2:
        danger += 1

    if scarcity <= likely_units:
        base_bid = 18
    elif supply >= 22:
        base_bid = 24
    elif supply >= 19:
        base_bid = 32
    else:
        base_bid = 42

    if highest_prev >= 145:
        if danger >= 5:
            bid = 112
        elif danger >= 3:
            bid = 58
        else:
            bid = base_bid
    elif highest_prev >= 120:
        if danger >= 5:
            bid = 95
        elif danger >= 3:
            bid = 52
        else:
            bid = max(base_bid, 28)
    elif highest_prev > 0:
        if danger >= 5:
            bid = min(90, highest_prev + 3)
        elif danger >= 3:
            bid = min(70, avg_prev + 2)
        else:
            bid = max(base_bid, avg_prev * 0.45)
    else:
        if danger >= 5:
            bid = 84
        elif danger >= 3:
            bid = 48
        else:
            bid = base_bid

    if rich_opponents >= 3 and danger <= 2:
        bid *= 0.85

    if day >= 8:
        if hp >= 6 and no_water_days == 0:
            bid *= 0.9
        elif danger >= 4:
            bid *= 1.08

    if hp <= 1 or no_water_days >= 2:
        bid = max(bid, 105)

    if budget < 80:
        bid = min(bid, budget * 0.72)
    elif budget < 140:
        bid = min(bid, budget * 0.82)
    else:
        bid = min(bid, budget * 0.9)

    if bid < 0:
        bid = 0

    return float(min(budget, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < 18:
        return min(my_status['budget'], avg_prev_bid * 1.1)

    return min(my_status['budget'], max(40, avg_prev_bid * 0.9))
